arguments.command:
cd /workspace && source dev.sh && python3 - <<'PYEOF'
import ast, os, sys
root='/workspace/submission'
for base,dirs,files in os.walk(root):
    for f in sorted(files):
        if not f.endswith('.py'): continue
        p=os.path.join(base,f)
        tree=ast.parse(open(p).read())
        imported=set()
        for node in ast.walk(tree):
            if isinstance(node,ast.Import):
                for a in node.names: imported.add((a.asname or a.name).split('.')[0])
            elif isinstance(node,ast.ImportFrom):
                for a in node.names:
                    if a.name!='*': imported.add(a.asname or a.name)
        src=open(p).read()
        used=set()
        for n in ast.walk(tree):
            if isinstance(n,ast.Name): used.add(n.id)
            if isinstance(n,ast.Attribute): pass
        # crude textual usage count
        unused=[i for i in imported if src.count(i)<=1]
        if unused: print(os.path.relpath(p,root), 'possibly unused:', unused)
PYEOF
